    codeSnippet: "class RateLimitInterceptor extends Interceptor {\n  final int maxRequests;\n  final Duration window;\n  final _timestamps = <DateTime>[];\n  final _queue = <Completer<void>>[];\n  \n  RateLimitInterceptor({this.maxRequests = 10, this.window = const Duration(seconds: 1)});\n  \n  @override\n  void onRequest(RequestOptions options, RequestInterceptorHandler handler) async {\n    await _waitForSlot();\n    _timestamps.add(DateTime.now());\n    handler.next(options);\n  }\n  \n  Future<void> _waitForSlot() async {\n    _timestamps.removeWhere((t) => DateTime.now().difference(t) > window);\n    if (_timestamps.length >= maxRequests) {\n      final completer = Completer<void>();\n      _queue.add(completer);\n      final waitTime = window - DateTime.now().difference(_timestamps.first);\n      Future.delayed(waitTime, () {\n        _queue.remove(completer);\n        completer.complete();\n      });\n      await completer.future;\n    }\n  }\n}",
