    codeSnippet: "class RequestCoalescer<K, V> {\n  final Map<K, _CoalescedRequest<V>> _active = {};\n  final Future<V> Function(K) _fetcher;\n  \n  RequestCoalescer(this._fetcher);\n  \n  Future<V> get(K key) {\n    if (_active.containsKey(key)) {\n      return _active[key]!.future;\n    }\n    \n    final completer = Completer<V>();\n    _active[key] = _CoalescedRequest(completer);\n    \n    _fetcher(key).then((value) {\n      completer.complete(value);\n    }).catchError((error) {\n      completer.completeError(error);\n    }).whenComplete(() {\n      _active.remove(key);\n    });\n    \n    return completer.future;\n  }\n}",
